/usr/bin/zsh -lc "mkdir -p specs/hal-engine-tool-input-validation .lore; cat > src/orchestration/tools/registry.acceptance.test.ts <<'EOF'
import {ToolRegistry} from './registry.js';

describe('ToolRegistry input validation', () => {
  it('rejects missing required input before invoking the executor', async () => {
    const registry = new ToolRegistry();
    let calls = 0;
    registry.register(
      {
        name: 'weather',
        description: 'Get the weather',
        inputSchema: {
          type: 'object',
          properties: {location: {type: 'string'}},
          required: ['location'],
        },
      },
      async () => {
        calls += 1;
        return 'forecast';
      }
    );

    const response = await registry.execute('weather', {});

    expect({result: response.result, calls}).toEqual({
      result: expect.stringContaining('location'),
      calls: 0,
    });
  });
});
EOF
